pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        c.sendMoney(address(c), 1 ether);
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == 1 ether);
    }
}
